"use client";

import { useEffect, useLayoutEffect, useRef, useState } from "react";
import { Command as CommandPrimitive } from "cmdk";
import {
  ArrowUpRight,
  FileSearch,
  LoaderCircle,
  Search,
  X,
} from "lucide-react";
import { useLanguage } from "@/hooks/use-language";
import { integrationErrorMessage } from "@/hooks/use-integration-operation";
import { Button } from "@/components/ui/button";
import type { CommandItem } from "@/components/ui/command";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogTitle,
} from "@/components/ui/dialog";
import type {
  IntegrationErrorCode,
  IntegrationSearchHit,
} from "@/lib/integrations/contracts";
import {
  createSearchBridgeSession,
  filterShellNavigation,
  searchBridgeErrorCode,
  searchBridgeHref,
  type ShellSearchAdapter,
  type ShellSearchResult,
} from "@/lib/integrations/search-bridge";

type SearchState = {
  adapter?: ShellSearchAdapter;
  workspaceId: string;
  query: string;
  status: "idle" | "pending" | "success" | "error" | "cancelled";
  result?: ShellSearchResult;
  errorCode?: IntegrationErrorCode;
};

function useShellSearch({
  adapter,
  workspaceId,
  query,
  open,
  enabled,
}: {
  adapter?: ShellSearchAdapter;
  workspaceId: string;
  query: string;
  open: boolean;
  enabled: boolean;
}) {
  const [session] = useState(createSearchBridgeSession);
  const [revision, setRevision] = useState(0);
  const sequence = useRef(0);
  const text = query.trim();
  const [state, setState] = useState<SearchState>({
    workspaceId,
    query: "",
    status: "idle",
  });

  // Invalidate during commit, before a passive effect or an ignored abort can
  // publish data belonging to the previous provider, workspace or query.
  useLayoutEffect(() => {
    sequence.current += 1;
    session.cancel();
    return () => {
      sequence.current += 1;
      session.cancel();
    };
  }, [adapter, workspaceId, text, open, enabled, revision, session]);

  useEffect(() => {
    const ticket = sequence.current;
    const context = { adapter, workspaceId, query: text };
    if (!open || !enabled || !adapter || !text) {
      setState({ ...context, status: "idle" });
      return;
    }
    setState({ ...context, status: "pending" });
    const timer = setTimeout(() => {
      if (ticket !== sequence.current) return;
      void session
        .run(adapter, { workspaceId, query: text })
        .then((result) => {
          if (!result || ticket !== sequence.current) return;
          setState({ ...context, status: "success", result });
        })
        .catch((cause: unknown) => {
          if (ticket !== sequence.current) return;
          setState({
            ...context,
            status: "error",
            errorCode: searchBridgeErrorCode(cause),
          });
        });
    }, 200);
    return () => clearTimeout(timer);
  }, [adapter, workspaceId, text, open, enabled, revision, session]);

  const current =
    open &&
    enabled &&
    state.adapter === adapter &&
    state.workspaceId === workspaceId &&
    state.query === text;
  const visibleState: SearchState = current
    ? state
    : { workspaceId, query: text, status: "idle" };
  return {
    state: visibleState,
    retry: () => setRevision((value) => value + 1),
    cancel: () => {
      sequence.current += 1;
      session.cancel();
      setState({
        adapter,
        workspaceId,
        query: text,
        status: "cancelled",
      });
    },
  };
}

type SearchBridgeCommandProps = {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  items: CommandItem[];
  label: string;
  placeholder: string;
  emptyLabel: string;
  closeLabel: string;
  search: string;
  onSearchChange: (value: string) => void;
  workspaceId: string;
  enabled: boolean;
  adapter?: ShellSearchAdapter;
  onNavigate: (href: string) => void;
};

/** Reuses the shell's dialog and cmdk keyboard behavior without filtering source ranking. */
export function SearchBridgeCommand({
  open,
  onOpenChange,
  items,
  label,
  placeholder,
  emptyLabel,
  closeLabel,
  search,
  onSearchChange,
  workspaceId,
  enabled,
  adapter,
  onNavigate,
}: SearchBridgeCommandProps) {
  const { l, locale, number } = useLanguage();
  const localPreview = adapter?.mode === "demo";
  const request = useShellSearch({
    adapter,
    workspaceId,
    query: search,
    open,
    enabled,
  });
  const navigation = filterShellNavigation(items, search);
  const groups = [...new Set(navigation.map((item) => item.group ?? ""))];
  const hits = request.state.result?.hits ?? [];
  const [preview, setPreview] = useState<{
    hit: IntegrationSearchHit;
    adapter?: ShellSearchAdapter;
    workspaceId: string;
    query: string;
  } | null>(null);
  const visiblePreview =
    preview &&
    open &&
    request.state.status === "success" &&
    request.state.result?.hits.includes(preview.hit) &&
    preview.adapter === adapter &&
    preview.workspaceId === workspaceId &&
    preview.query === search.trim()
      ? preview.hit
      : null;

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent
        className="min-w-0 overflow-hidden p-0"
        closeLabel={closeLabel}
      >
        <DialogTitle className="sr-only">{label}</DialogTitle>
        <DialogDescription className="sr-only">
          {adapter
            ? l(
                "Search authorized workspace sources and navigate with the arrow keys.",
                "Busca en las fuentes autorizadas del espacio y navega con las flechas.",
              )
            : placeholder}
        </DialogDescription>
        <CommandPrimitive label={label} shouldFilter={false}>
          <div className="flex items-center gap-3 border-b border-border px-5 pr-12">
            <Search
              className="size-4 shrink-0 text-muted-foreground"
              aria-hidden
            />
            <CommandPrimitive.Input
              value={search}
              onValueChange={onSearchChange}
              placeholder={placeholder}
              maxLength={2000}
              className="h-14 min-w-0 flex-1 bg-transparent text-sm outline-none"
            />
          </div>
          {adapter && (
            <div className="border-b border-border bg-surface-subtle/40 px-5 py-3">
              {request.state.status === "pending" ? (
                <div className="flex flex-wrap items-center justify-between gap-2">
                  <p
                    role="status"
                    className="flex items-center gap-2 text-xs text-muted-foreground"
                  >
                    <LoaderCircle
                      className="size-3.5 motion-safe:animate-spin"
                      aria-hidden
                    />
                    {l(
                      "Searching this workspace…",
                      "Buscando en este espacio…",
                    )}
                  </p>
                  <Button variant="ghost" size="sm" onClick={request.cancel}>
                    {l("Cancel search", "Cancelar búsqueda")}
                  </Button>
                </div>
              ) : request.state.status === "error" ? (
                <div className="flex flex-wrap items-center justify-between gap-2">
                  <p
                    role="alert"
                    className="max-w-sm text-xs leading-6 text-destructive-foreground"
                  >
                    {integrationErrorMessage(
                      request.state.errorCode ?? "provider-error",
                      locale,
                    )}
                  </p>
                  <Button variant="outline" size="sm" onClick={request.retry}>
                    {l("Retry search", "Reintentar búsqueda")}
                  </Button>
                </div>
              ) : request.state.status === "cancelled" ? (
                <div className="flex flex-wrap items-center justify-between gap-2">
                  <p
                    role="status"
                    className="text-xs leading-6 text-muted-foreground"
                  >
                    {l(
                      "Search cancelled. Your query is still here.",
                      "Búsqueda cancelada. La consulta sigue aquí.",
                    )}
                  </p>
                  <Button variant="outline" size="sm" onClick={request.retry}>
                    {l("Retry search", "Reintentar búsqueda")}
                  </Button>
                </div>
              ) : request.state.status === "success" ? (
                <p
                  role="status"
                  className="text-xs leading-6 text-muted-foreground"
                >
                  {hits.length
                    ? `${number(request.state.result?.total ?? 0)} ${
                        localPreview
                          ? l(
                              "local preview results",
                              "resultados de la demo local",
                            )
                          : l("connected results", "resultados conectados")
                      }`
                    : l(
                        "No connected items returned. Try different terms or an authorized source.",
                        "No se devolvieron elementos conectados. Prueba otros términos o una fuente autorizada.",
                      )}
                </p>
              ) : (
                <p
                  role="status"
                  className="text-xs leading-6 text-muted-foreground"
                >
                  {enabled
                    ? localPreview
                      ? l(
                          "Type to search the local workspace preview.",
                          "Escribe para buscar en la demo local del espacio.",
                        )
                      : l(
                          "Type to search your connected workspace.",
                          "Escribe para buscar en tu espacio conectado.",
                        )
                    : l(
                        "Preparing this workspace…",
                        "Preparando este espacio…",
                      )}
                </p>
              )}
            </div>
          )}
          <CommandPrimitive.List className="max-h-[min(60vh,400px)] overflow-y-auto p-2">
            {request.state.status !== "pending" && (
              <CommandPrimitive.Empty className="p-8 text-center text-xs text-muted-foreground">
                {adapter
                  ? l(
                      "No navigation matches this query.",
                      "Ninguna ruta coincide con esta consulta.",
                    )
                  : emptyLabel}
              </CommandPrimitive.Empty>
            )}
            {hits.length > 0 && (
              <CommandPrimitive.Group
                heading={
                  localPreview
                    ? l("Local workspace preview", "Demo local del espacio")
                    : l("Connected workspace", "Espacio conectado")
                }
                className="[&_[cmdk-group-heading]]:px-3 [&_[cmdk-group-heading]]:py-2 [&_[cmdk-group-heading]]:text-[10px] [&_[cmdk-group-heading]]:font-semibold [&_[cmdk-group-heading]]:text-muted-foreground"
              >
                {hits.map((hit, index) => (
                  <CommandPrimitive.Item
                    key={`${hit.source}:${hit.id}:${index}`}
                    value={`connected-result-${index}`}
                    onSelect={() => {
                      const href = searchBridgeHref(hit.url);
                      if (href) {
                        onNavigate(href);
                        onOpenChange(false);
                      } else {
                        setPreview({
                          hit,
                          adapter,
                          workspaceId,
                          query: search.trim(),
                        });
                      }
                    }}
                    className="flex min-h-11 cursor-default items-start gap-3 rounded-lg px-3 py-3 text-xs aria-selected:bg-accent aria-selected:text-accent-foreground"
                  >
                    <FileSearch
                      className="mt-0.5 size-4 shrink-0 text-primary"
                      aria-hidden
                    />
                    <span className="min-w-0 flex-1">
                      <span className="block break-words font-medium">
                        {hit.title}
                      </span>
                      <span className="mt-1 block truncate text-[10px] text-muted-foreground">
                        {hit.source}
                      </span>
                      {hit.snippet && (
                        <span className="mt-1 line-clamp-2 block break-words text-[11px] leading-5 text-muted-foreground">
                          {hit.snippet}
                        </span>
                      )}
                    </span>
                    {hit.url && (
                      <ArrowUpRight
                        className="mt-0.5 size-3.5 shrink-0 text-muted-foreground"
                        aria-hidden
                      />
                    )}
                  </CommandPrimitive.Item>
                ))}
              </CommandPrimitive.Group>
            )}
            {groups.map((group) => (
              <CommandPrimitive.Group
                key={group}
                heading={group || undefined}
                className="[&_[cmdk-group-heading]]:px-3 [&_[cmdk-group-heading]]:py-2 [&_[cmdk-group-heading]]:text-[10px] [&_[cmdk-group-heading]]:font-semibold [&_[cmdk-group-heading]]:text-muted-foreground"
              >
                {navigation
                  .filter((item) => (item.group ?? "") === group)
                  .map((item) => (
                    <CommandPrimitive.Item
                      key={item.id}
                      value={`navigation:${item.id}`}
                      onSelect={() => {
                        item.onSelect();
                        onOpenChange(false);
                      }}
                      className="flex min-h-11 cursor-default items-center gap-3 rounded-md px-3 py-2.5 text-xs aria-selected:bg-accent aria-selected:text-accent-foreground [&_svg]:size-4"
                    >
                      {item.icon}
                      {item.label}
                    </CommandPrimitive.Item>
                  ))}
              </CommandPrimitive.Group>
            ))}
          </CommandPrimitive.List>
        </CommandPrimitive>
        {visiblePreview && (
          <section
            aria-label={l(
              "Search result preview",
              "Vista previa del resultado",
            )}
            className="max-h-52 overflow-y-auto border-t border-border bg-surface-subtle/40 p-5"
          >
            <div className="flex items-start justify-between gap-3">
              <h3 className="min-w-0 break-words text-sm font-semibold">
                {visiblePreview.title}
              </h3>
              <Button
                size="icon-sm"
                variant="ghost"
                aria-label={l(
                  "Close result preview",
                  "Cerrar vista previa del resultado",
                )}
                onClick={() => setPreview(null)}
              >
                <X className="size-4" aria-hidden />
              </Button>
            </div>
            <p className="mt-2 break-words text-xs leading-6">
              {visiblePreview.snippet ||
                l(
                  "This source supplied a title without a passage.",
                  "Esta fuente proporcionó un título sin fragmento.",
                )}
            </p>
            <p className="mt-2 break-words text-[10px] text-muted-foreground">
              {visiblePreview.source}
            </p>
          </section>
        )}
      </DialogContent>
    </Dialog>
  );
}

"use client";
import * as React from "react";
import { Button as ButtonPrimitive } from "@base-ui/react/button";
import { cva, type VariantProps } from "class-variance-authority";
import { LoaderCircle } from "lucide-react";
import { cn } from "@/lib/utils";
import "@/styles/effects.css";

export const buttonVariants = cva(
  "af-button af-control inline-flex shrink-0 items-center justify-center gap-2 whitespace-nowrap border border-transparent text-[13px] leading-5 font-semibold tracking-[-.01em] outline-none transition-[background-color,border-color,color,box-shadow,transform] duration-[var(--af-motion-fast,150ms)] active:scale-[.98] motion-reduce:transform-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background disabled:pointer-events-none disabled:opacity-45 data-disabled:pointer-events-none data-disabled:opacity-45 [@media(pointer:coarse)]:min-h-11 [@media(pointer:coarse)]:min-w-11 [&_svg]:size-4 [&_svg]:shrink-0",
  {
    variants: {
      variant: {
        default:
          "af-button-primary bg-primary text-primary-foreground hover:bg-[color:var(--af-shade-primary,var(--primary-hover))]",
        outline:
          "af-button-outline border-border bg-surface text-foreground [background-image:none] hover:border-primary/40 hover:bg-[color:var(--af-shade-outline,var(--surface-subtle))]",
        secondary:
          "af-button-surface bg-accent text-accent-foreground [background-image:none] hover:bg-[color:var(--af-shade-surface,var(--accent))] hover:text-foreground",
        ghost:
          "bg-transparent text-muted-foreground hover:bg-surface-subtle hover:text-foreground",
        destructive:
          "af-button-destructive bg-destructive text-destructive-foreground [background-image:none] hover:bg-[color:var(--af-shade-destructive,var(--destructive))]",
        link: "af-hover-link bg-transparent text-primary underline underline-offset-4 hover:text-primary-hover",
      },
      size: {
        sm: "h-8 px-3",
        default: "h-[var(--af-control-height,40px)] px-4",
        lg: "h-12 px-6 text-sm",
        icon: "size-[var(--af-control-height,40px)]",
        "icon-sm": "size-8",
      },
      shape: {
        rounded: "rounded-[var(--radius-md,10px)]",
        pill: "rounded-full",
        square: "rounded-none",
      },
    },
    defaultVariants: { variant: "default", size: "default", shape: "rounded" },
  },
);
export type ButtonShape = "rounded" | "pill" | "square";
export type ButtonAppearance =
  "solid" | "soft" | "outline" | "glass" | "gradient";
const appearanceClasses: Record<ButtonAppearance, string> = {
  solid: "[background-image:none]",
  soft: "border-primary/25 bg-accent text-accent-foreground [background-image:none] hover:bg-[color:var(--af-shade-surface)] hover:text-foreground",
  outline:
    "border-primary/40 bg-surface text-foreground [background-image:none] hover:bg-[color:var(--af-shade-outline)] hover:text-foreground",
  glass:
    "border-primary/30 bg-[var(--af-glass-background)] text-foreground hover:bg-[var(--af-glass-background)] hover:text-foreground",
  gradient:
    "border-transparent bg-primary text-primary-foreground [background-image:var(--af-gradient-primary)] hover:bg-primary-hover hover:text-primary-foreground",
};
export type ButtonProps = Omit<
  React.ComponentProps<typeof ButtonPrimitive>,
  "className"
> &
  VariantProps<typeof buttonVariants> & {
    className?: string;
    loading?: boolean;
    appearance?: ButtonAppearance;
  };
export function Button({
  className,
  variant,
  size,
  shape,
  loading,
  appearance,
  children,
  disabled,
  focusableWhenDisabled,
  "aria-label": ariaLabel,
  "aria-labelledby": ariaLabelledBy,
  "aria-busy": ariaBusy,
  ...props
}: ButtonProps) {
  const labelId = React.useId();
  return (
    <ButtonPrimitive
      {...props}
      data-slot="button"
      data-variant={variant ?? "default"}
      data-size={size ?? "default"}
      data-shape={shape ?? "rounded"}
      data-appearance={appearance}
      className={cn(
        buttonVariants({ variant, size, shape }),
        appearance && `af-control-${appearance}`,
        appearance &&
          variant !== "destructive" &&
          appearanceClasses[appearance],
        className,
      )}
      disabled={disabled || loading}
      focusableWhenDisabled={focusableWhenDisabled ?? loading}
      aria-busy={loading || ariaBusy}
      aria-label={ariaLabel}
      aria-labelledby={
        ariaLabelledBy ?? (loading && !ariaLabel ? labelId : undefined)
      }
    >
      {loading && (
        <LoaderCircle
          className="motion-safe:animate-spin motion-reduce:animate-none [[data-motion-level=off]_&]:animate-none"
          aria-hidden="true"
        />
      )}
      <span id={labelId} className="contents">
        {children}
      </span>
    </ButtonPrimitive>
  );
}

"use client";
import { Command as CommandPrimitive } from "cmdk";
import { Search } from "lucide-react";
import {
  Dialog,
  DialogContent,
  DialogTitle,
  DialogDescription,
} from "@/components/ui/dialog";
export type CommandItem = {
  id: string;
  label: string;
  group?: string;
  icon?: React.ReactNode;
  onSelect: () => void;
  keywords?: string[];
};
export function Command({
  open,
  onOpenChange,
  items,
  label,
  placeholder,
  emptyLabel,
  closeLabel,
  search,
  onSearchChange,
}: {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  items: CommandItem[];
  label: string;
  placeholder: string;
  emptyLabel: string;
  closeLabel?: string;
  search?: string;
  onSearchChange?: (value: string) => void;
}) {
  const groups = [...new Set(items.map((item) => item.group ?? ""))];
  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="p-0" closeLabel={closeLabel}>
        <DialogTitle className="sr-only">{label}</DialogTitle>
        <DialogDescription className="sr-only">{placeholder}</DialogDescription>
        <CommandPrimitive label={label}>
          <div className="flex items-center gap-3 border-b border-border px-5 pr-12">
            <Search className="size-4 text-muted-foreground" />
            <CommandPrimitive.Input
              value={search}
              onValueChange={onSearchChange}
              placeholder={placeholder}
              className="h-14 min-w-0 flex-1 bg-transparent text-sm outline-none"
            />
          </div>
          <CommandPrimitive.List className="max-h-[min(60vh,400px)] overflow-y-auto p-2">
            <CommandPrimitive.Empty className="p-8 text-center text-xs text-muted-foreground">
              {emptyLabel}
            </CommandPrimitive.Empty>
            {groups.map((group) => (
              <CommandPrimitive.Group
                key={group}
                heading={group || undefined}
                className="[&_[cmdk-group-heading]]:px-3 [&_[cmdk-group-heading]]:py-2 [&_[cmdk-group-heading]]:text-[10px] [&_[cmdk-group-heading]]:font-semibold [&_[cmdk-group-heading]]:text-muted-foreground"
              >
                {items
                  .filter((item) => (item.group ?? "") === group)
                  .map((item) => (
                    <CommandPrimitive.Item
                      key={item.id}
                      value={item.label}
                      keywords={item.keywords}
                      onSelect={() => {
                        item.onSelect();
                        onOpenChange(false);
                      }}
                      className="flex cursor-default items-center gap-3 rounded-md px-3 py-2.5 text-xs aria-selected:bg-accent aria-selected:text-accent-foreground [&_svg]:size-4"
                    >
                      {item.icon}
                      {item.label}
                    </CommandPrimitive.Item>
                  ))}
              </CommandPrimitive.Group>
            ))}
          </CommandPrimitive.List>
        </CommandPrimitive>
      </DialogContent>
    </Dialog>
  );
}

"use client";
import * as React from "react";
import { Dialog as DialogPrimitive } from "@base-ui/react/dialog";
import { X } from "lucide-react";
import { cn } from "@/lib/utils";
export const Dialog = DialogPrimitive.Root;
export const DialogTrigger = DialogPrimitive.Trigger;
export const DialogClose = DialogPrimitive.Close;
export function DialogContent({
  children,
  className,
  closeLabel = "Close",
  ...props
}: Omit<React.ComponentProps<typeof DialogPrimitive.Popup>, "className"> & {
  className?: string;
  closeLabel?: string;
}) {
  return (
    <DialogPrimitive.Portal>
      <DialogPrimitive.Backdrop className="fixed inset-0 z-60 bg-black/35 backdrop-blur-[2px] transition-opacity data-ending-style:opacity-0 data-starting-style:opacity-0" />
      <DialogPrimitive.Popup
        className={cn(
          "fixed top-1/2 left-1/2 z-60 max-h-[90dvh] w-[calc(100%-32px)] max-w-lg -translate-x-1/2 -translate-y-1/2 overflow-y-auto rounded-xl border border-border bg-surface p-6 text-foreground shadow-2xl outline-none",
          className,
        )}
        {...props}
      >
        {children}
        <DialogPrimitive.Close
          aria-label={closeLabel}
          className="absolute top-4 right-4 rounded-md p-1.5 text-muted-foreground outline-none hover:bg-surface-subtle focus-visible:ring-2 focus-visible:ring-ring"
        >
          <X className="size-4" />
        </DialogPrimitive.Close>
      </DialogPrimitive.Popup>
    </DialogPrimitive.Portal>
  );
}
export function DialogTitle({
  className,
  ...props
}: Omit<React.ComponentProps<typeof DialogPrimitive.Title>, "className"> & {
  className?: string;
}) {
  return (
    <DialogPrimitive.Title
      className={cn("pr-7 text-lg font-semibold tracking-tight", className)}
      {...props}
    />
  );
}
export function DialogDescription({
  className,
  ...props
}: Omit<
  React.ComponentProps<typeof DialogPrimitive.Description>,
  "className"
> & { className?: string }) {
  return (
    <DialogPrimitive.Description
      className={cn(
        "mt-2 text-sm leading-relaxed text-muted-foreground",
        className,
      )}
      {...props}
    />
  );
}
export function DialogFooter({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div className={cn("mt-6 flex justify-end gap-2", className)} {...props} />
  );
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import { useLanguage } from "@/hooks/use-language";
import {
  IntegrationError,
  type IntegrationAction,
  type IntegrationErrorCode,
  type IntegrationResult,
  type IntegrationValues,
  type IntegrationWorkbenchProps,
} from "@/lib/integrations/contracts";
import { parseIntegrationResult } from "@/lib/integrations/validation";
import {
  createIntegrationRequestKeys,
  integrationRequestSignature,
} from "@/lib/integrations/request-keys";

const messages: Record<IntegrationErrorCode, [string, string]> = {
  "configuration-required": [
    "Configure this connection before running an action.",
    "Configura esta conexión antes de ejecutar una acción.",
  ],
  "permission-denied": [
    "This connection does not have the required permission.",
    "Esta conexión no tiene el permiso necesario.",
  ],
  expired: [
    "Reconnect this account to continue.",
